                row.put("discountReason", r.get("DISCOUNT_REASON"));
            }
            if (r.get("SUPPLY_REGION") != null) {
                row.put("supplyRegion", r.get("SUPPLY_REGION"));
            }
            row.put("lineItems", jdbc.queryForList(
