                        line.put("overtime", l.get("OVERTIME"));
                        line.put("discountPct", l.get("DISCOUNT_PCT"));
                        if (l.get("TAX_RATE") != null) {
                            line.put("taxRate", l.get("TAX_RATE"));
                        }
                        if (l.get("CREDIT_OF_LINE") != null) {
                            line.put("creditOfLine", l.get("CREDIT_OF_LINE"));
                        }
                        return line;
                    }).toList());
            return row;
        }).toList());
